#!/bin/sh
case "${HERDR_FIXTURE_MODE:-valid}" in
  invalid) printf '%s\n' '---' 'name: other' 'description: wrong binary output' '---' ;;
  failure) exit 2 ;;
  *) printf '%s\n' '---' 'name: herdr' 'description: Control the installed Herdr binary' '---' '# Herdr' ;;
esac

