import { afterEach, expect, test } from 'bun:test';
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const binary = resolve('bin/herdr');
const source = resolve('generated/skills/herdr/SKILL.md');
const installed = resolve('site/skills/herdr/SKILL.md');
const installedBinary = readFileSync(binary, 'utf8');

function run(entry, mode = 'valid', executable = binary) {
  return Bun.spawnSync([process.execPath, entry, 'minimal'], {
    env: { ...process.env, HERDR_BINARY: executable, HERDR_FIXTURE_MODE: mode },
    stdout: 'pipe',
    stderr: 'pipe',
  });
}

afterEach(() => {
  writeFileSync(binary, installedBinary);
  rmSync('site', { recursive: true, force: true });
  rmSync('generated', { recursive: true, force: true });
});

test('minimal installation exposes the skill emitted by the installed binary', () => {
  expect(run('install-profile.mjs').exitCode).toBe(0);
  expect(existsSync(source)).toBe(true);
  expect(existsSync(installed)).toBe(true);
  expect(readFileSync(installed, 'utf8')).toBe(readFileSync(source, 'utf8'));
  expect(readFileSync(source, 'utf8')).toContain('name: herdr');
});

test.each(['invalid', 'failure', 'missing'])('%s generation preserves the previous valid skill', (mode) => {
  mkdirSync('generated/skills/herdr', { recursive: true });
  writeFileSync(source, 'previous valid source\n');
  const result = run('install-profile.mjs', mode, mode === 'missing' ? '/nonexistent/herdr' : binary);
  expect(result.exitCode).not.toBe(0);
  expect(readFileSync(source, 'utf8')).toBe('previous valid source\n');
});

test('upgrade refreshes the generated skill after binary output changes', () => {
  expect(run('install-profile.mjs').exitCode).toBe(0);
  writeFileSync(binary, '#!/bin/sh\nprintf "%s\\n" "---" "name: herdr" "description: Updated Herdr" "---" "# Updated"\n');
  expect(run('upgrade.mjs').exitCode).toBe(0);
  expect(readFileSync(source, 'utf8')).toContain('description: Updated Herdr');
});

