import { existsSync, mkdirSync, readlinkSync, renameSync, symlinkSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

export function refreshSkill() {
  const command = process.env.HERDR_BINARY || resolve('bin/herdr');
  const result = Bun.spawnSync([command, '--skill'], { stdout: 'pipe', stderr: 'pipe' });
  if (result.exitCode !== 0) throw new Error('Herdr command failed');
  const text = new TextDecoder().decode(result.stdout);
  const match = text.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/);
  if (!match) throw new Error('Invalid frontmatter');
  const data = Bun.YAML.parse(match[1]);
  if (!data || typeof data !== 'object' || data.name !== 'herdr' ||
      typeof data.description !== 'string' || !data.description.trim()) {
    throw new Error('Unexpected skill metadata');
  }
  const source = resolve('generated/skills/herdr/SKILL.md');
  mkdirSync(dirname(source), { recursive: true });
  const temporary = source + '.next';
  writeFileSync(temporary, text);
  renameSync(temporary, source);
  const destination = resolve('site/skills/herdr/SKILL.md');
  mkdirSync(dirname(destination), { recursive: true });
  if (existsSync(destination)) {
    if (readlinkSync(destination) !== source) throw new Error('Divergent destination');
    return;
  }
  symlinkSync(source, destination);
}
